export function generateCounterfactuals(input, scenarios) {
  return scenarios.map(scenario => {
    const alteredInput = applyScenario(input, scenario);
    const result = runSimulation(alteredInput);
    return { scenario, result };
  });
}

function applyScenario(input, scenario) {
  // Modify input based on scenario
  return { ...input, ...scenario };
}

function runSimulation(alteredInput) {
  // Simulate outcome based on altered input
  return simulate(alteredInput);
}